export interface ISqlAdapter<TClient = unknown> {
  query: <T = unknown>(sql: string, params?: unknown[]) => Promise<T[]>;
  execute: (sql: string, params?: unknown[]) => Promise<unknown>;
  getClient: () => TClient;
}

import { Injectable, Inject } from '@nestjs/common';
import { ISqlAdapter } from '../interfaces/db-adapter.interface.js';
import type { PrismaClient } from '../../orm/prisma/generated/client.js';



@Injectable()
export class PrismaSqlAdapter implements ISqlAdapter<PrismaClient> {
  constructor(
    @Inject('PRISMA_SQL_CLIENT') private readonly prisma: PrismaClient
  ) {}

  query<T = unknown>(sql: string, params: unknown[] = []): Promise<T[]> {
    return this.prisma.$queryRawUnsafe<T[]>(sql, ...params);
  }

  execute(sql: string, params: unknown[] = []): Promise<number> {
    return this.prisma.$executeRawUnsafe(sql, ...params);
  }

  getClient(): PrismaClient {
    return this.prisma;
  }

  async onModuleDestroy(): Promise<void> {
    await this.prisma.$disconnect();
  }
}

import { DynamicModule, Module, Global, Provider } from '@nestjs/common';
import { DbService } from './db.service.js';

import { PrismaClient } from '../database/orm/prisma/generated/client.js';
import { PrismaSqlAdapter } from './adapters/sql/prisma-sql.adapter.js';
import { PrismaMssql } from '@prisma/adapter-mssql';




export interface DbModuleOptions {
  sqlserver?: { server: string; port: number; database: string; user: string; password: string; options: { encrypt: boolean; trustServerCertificate: boolean } };
}

@Global()
@Module({})
export class DbModule {
  static forRoot(options: DbModuleOptions): DynamicModule {
    const initialProviders: Provider[] = [DbService];
    const providers = initialProviders;

    if (!options.sqlserver) {
      throw new Error("SQL Server connection settings are required to initialize Prisma");
    }
    const sqlAdapter = new PrismaMssql(options.sqlserver);
    const prismaSql = new PrismaClient({ adapter: sqlAdapter });
    providers.push({
      provide: 'PRISMA_SQL_CLIENT',
      useValue: prismaSql,
    }, {
      provide: 'SQL_ADAPTER',
      useClass: PrismaSqlAdapter,
    });





    return {
      exports: [DbService],
      module: DbModule,
      providers,
    };
  }
}

import { Injectable, Inject } from '@nestjs/common';
import type { ISqlAdapter } from './adapters/interfaces/db-adapter.interface.js';
import type { PrismaClient } from './orm/prisma/generated/client.js';

type SqlClient = PrismaClient;


@Injectable()
export class DbService {
  constructor(
    @Inject('SQL_ADAPTER') readonly sql: ISqlAdapter<SqlClient>
  ) {}

  get raw() {
    return {
      sql: this.sql.getClient(),
    };
  }
  get prisma(): PrismaClient {
    return this.sql.getClient();
  }
}

